@push('scripts')
<script>
$(function(){var $table=$('#locations-table'),text=$.fn.dataTable.render.text(),types={BRANCH:'สาขา',WAREHOUSE:'คลัง',BUILDING:'อาคาร',FLOOR:'ชั้น',ROOM:'ห้อง',SITE:'พื้นที่',OTHER:'อื่น ๆ'},columns=[{data:'code',name:'asset_locations.code',render:text.display},{data:'name',name:'asset_locations.name',render:text.display},{data:'location_type',name:'asset_locations.location_type',render:function(v,t){return t==='display'?text.display(types[v]||v):v;}},{data:null,name:'parents.code',render:function(v,t,row){var x=row.parent_code?(row.parent_code+' · '+row.parent_name):'-';return t==='display'?text.display(x):x;}},{data:null,name:'warehouses.code',render:function(v,t,row){var x=row.warehouse_code?(row.warehouse_code+' · '+row.warehouse_name):'-';return t==='display'?text.display(x):x;}},{data:'is_active',name:'asset_locations.is_active',searchable:false,render:function(v,t){return t==='display'?'<span class="badge '+(v?'text-bg-dark':'text-bg-secondary')+'">'+(v?'ใช้งาน':'ปิดใช้งาน')+'</span>':v;}}];if($table.data('can-manage'))columns.push({data:null,orderable:false,searchable:false,className:'text-end',render:function(v,t,row){if(t!=='display')return '';var a=[];if(row.edit_url)a.push('<a class="btn btn-sm btn-outline-dark" href="'+text.display(row.edit_url)+'"><i class="bx bx-edit me-1" aria-hidden="true"></i>แก้ไข</a>');if(row.delete_url)a.push('<button class="btn btn-sm btn-outline-danger js-delete-location" data-url="'+text.display(row.delete_url)+'" type="button"><i class="bx bx-trash me-1" aria-hidden="true"></i>ลบ</button>');return a.join(' ');}});var table=$table.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:$table.data('url'),data:function(data){data.is_active=$('#location-filter-status').val();}},order:[[0,'asc']],buttons:[window.erpExcelButton($table)],columns:columns}));$('#location-filter-status').on('change',function(){table.ajax.reload();});$('#location-filter-reset').on('click',function(){$('#location-filter-status').val('');table.ajax.reload();});window.erpAjaxDelete({button:'.js-delete-location',reload:'#locations-table',confirm:'ยืนยันการลบสถานที่นี้หรือไม่?'});});
</script>
